use twopointer::{two_sum, remove_duplicates, max_water};

#[test]
fn test_two_sum() {
    assert_eq!(two_sum(&[1, 2, 3, 4, 6], 6), Some((1, 3)));
    assert_eq!(two_sum(&[1, 2, 3], 10), None);
}

#[test]
fn test_remove_duplicates() {
    let mut v = vec![1, 1, 2, 2, 3];
    let len = remove_duplicates(&mut v);
    assert_eq!(len, 3);
    assert_eq!(&v[..len], &[1, 2, 3]);
}

#[test]
fn test_max_water() {
    assert_eq!(max_water(&[1, 8, 6, 2, 5, 4, 8, 3, 7]), 49);
    assert_eq!(max_water(&[1, 1]), 1);
}

#[test]
fn test_two_sum_empty() {
    let empty: Vec<i32> = vec![];
    assert_eq!(two_sum(&empty, 5), None);
}

#[test]
fn test_remove_duplicates_no_dups() {
    let mut v = vec![1, 2, 3];
    let len = remove_duplicates(&mut v);
    assert_eq!(len, 3);
    assert_eq!(&v[..len], &[1, 2, 3]);
}

